      \u0275\u0275elementStart(154, "h3", 38);
      \u0275\u0275text(155, "How AIDA collects its data");
      \u0275\u0275elementEnd();
      \u0275\u0275elementStart(156, "p");
      \u0275\u0275text(157, "When you add a Canada.ca page to your project, AIDA fetches information from the live English and French pages, the live content.json file, the task airtable, and from a static export of page visists from the UPD.");
      \u0275\u0275elementEnd();
      \u0275\u0275elementStart(158, "h4");
      \u0275\u0275text(159, "Page templates");
      \u0275\u0275elementEnd();
      \u0275\u0275elementStart(160, "p");
      \u0275\u0275text(161, `AIDA detects page templates based on specific criteria and puts that information in the "Template" column of your content inventory table. This helps give you an overview of what kind of pages you're working with. Here's what AIDA looks for:`);
      \u0275\u0275elementEnd();
