      \u0275\u0275elementStart(178, "li")(179, "strong");
      \u0275\u0275text(180, "old topic");
      \u0275\u0275elementEnd();
      \u0275\u0275text(181, " - has class ");
      \u0275\u0275elementStart(182, "code", 41);
      \u0275\u0275text(183, "list-group-item");
      \u0275\u0275elementEnd();
      \u0275\u0275text(184, " where more than 80% are links");
